{
  "name": "anchor_stamp",
  "description": "Calls the anchor-suite MCP server (server-to-server, not the browser CORS-gated relay) to timestamp one execution_hash, or batch-anchor an array via anchor-suite's own anchor_batch (one upstream call per batch, RFC 6962 Merkle root anchored, per-hash merkle_inclusion returned), and shapes the result as literal OCG v0.7 section 20 anchor_bindings entries ready to append to an artifact. Success is only reported after this tool independently confirms anchored_hash (or, for a batch entry, merkle_inclusion.leaf) equals the caller-supplied hash -- it does not merely trust anchor-suite's response. On ANY failure -- anchor-suite unreachable, erroring, timing out, or an equality mismatch -- returns {ok:false, unanchored:true, reason} verbatim, never a fabricated binding. Caller-invoked only; not wired into any automatic per-artifact-emission path.",
  "inputSchema": {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "properties": {
      "execution_hash": {
        "anyOf": [
          {
            "type": "string",
            "description": "A single sha256:... execution_hash to anchor."
          },
          {
            "minItems": 2,
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "2+ execution_hash values to batch-anchor in one upstream call (anchor_batch)."
          }
        ],
        "description": "The execution_hash(es) to anchor."
      },
      "authority": {
        "description": "Defaults to whatever anchor-suite's own anchor_hash/anchor_batch default to today (currently sigstore for rfc3161-tst) -- this tool does not own or hardcode a preference beyond that mirror.",
        "type": "string",
        "enum": [
          "rfc3161-tst",
          "opentimestamps"
        ]
      }
    },
    "required": [
      "execution_hash"
    ]
  }
}

{
  "name": "build_session_receipt",
  "description": "Aggregates execution_hashes from N ChainGraph tool calls in one agent session into a single SHA-256 Merkle root (session_receipt_root). Returns a tamper-evident session receipt and a regulator-framed PTG-01 audit prompt. One receipt covers an entire agent session: supply all execution_hashes in call order. The Merkle root is deterministic — the same hashes in the same order always produce the same root. Compliant with EU AI Act Art. 12 (transparency) and DORA ICT audit-trail requirements.",
  "inputSchema": {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "properties": {
      "execution_hashes": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Ordered list of execution_hash values from ChainGraph tool calls in this session (each produced by emit_chaingraph_artifact or a kernel tool). Minimum 1."
      },
      "tool_ids": {
        "description": "tool_id values corresponding to execution_hashes, in the same order. Used for the audit narrative.",
        "type": "array",
        "items": {
          "type": "string"
        }
      },
      "session_id": {
        "description": "Optional agent session identifier for the audit narrative (e.g. a UUID or timestamp).",
        "type": "string"
      },
      "framing": {
        "description": "Optional framing context for the PTG-01 regulator prompt (e.g. \"DORA incident review\" or \"EU AI Act Art.12 transparency log\").",
        "type": "string"
      },
      "prior_receipt": {
        "description": "An earlier receipt from this SAME session (its mmr_peaks/mmr_size/mmr_bagged_root). When supplied, execution_hashes MUST start with that earlier receipt's full leaf set — the response's consistency_proof then proves this receipt provably APPENDS to the prior one (CT-style append-only guarantee) without operating a log.",
        "type": "object",
        "properties": {
          "mmr_peaks": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "mmr_size": {
            "type": "number"
          },
          "mmr_bagged_root": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ]
          }
        },
        "required": [
          "mmr_peaks",
          "mmr_size"
        ]
      }
    },
    "required": [
      "execution_hashes"
    ]
  }
}

{
  "name": "verify_execution_hash",
  "description": "Independently verify a ChainGraph artifact (ChainGraph Standard v0.1 §6). Recomputes SHA-256 over the canonical (sorted-key, whitespace-stripped) JSON of policy_parameters + output_payload and compares it to the claimed execution_hash. A match proves the artifact's stated inputs deterministically produce its stated outputs. Pass either a full artifact object, or policy_parameters + output_payload + claimed_hash. Inputs must be I-JSON (RFC 7493): integers beyond 2^53 must be passed as JSON strings, and NaN/Infinity are rejected. Values outside I-JSON have no stable canonical form, so this tool returns a structured -32602 error (error.data.reason \"ijson_violation\") instead of a hash. Pure client-safe compute -- no data is stored. Use this to verify artifacts from any vendor that conforms to the ChainGraph Standard.",
  "inputSchema": {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "properties": {
      "artifact": {
        "description": "A full ChainGraph artifact envelope (must contain policy_parameters, output_payload, and execution_hash).",
        "type": "object",
        "propertyNames": {
          "type": "string"
        },
        "additionalProperties": {}
      },
      "policy_parameters": {
        "description": "Artifact policy_parameters (if not passing a full artifact).",
        "type": "object",
        "propertyNames": {
          "type": "string"
        },
        "additionalProperties": {}
      },
      "output_payload": {
        "description": "Artifact output_payload (if not passing a full artifact).",
        "type": "object",
        "propertyNames": {
          "type": "string"
        },
        "additionalProperties": {}
      },
      "claimed_hash": {
        "description": "The execution_hash to check against (if not passing a full artifact).",
        "type": "string"
      }
    }
  }
}

{
  "name": "verify_webbotauth_signature",
  "description": "Web Bot Auth Signature Verifier (RFC 9421): OpenChainGraph compute node (compliance_mandate). Deterministic OpenChainGraph compute node. By default (compute:\"auto\") inputs are computed server-side on Cloudflare Workers for gpu:false nodes with a registered kernel; compute:\"browser\" forces client-side execution and returns a browser delegation URL instead. gpu:true nodes always delegate to the browser. Inputs are processed transiently to compute the response and are not stored, logged, or retained. Use synthetic or anonymised inputs only. Exports an AP2 artifact with execution_hash for chain provenance. Output feeds: art-130-signature-directory-validator. Open at: https://ainumbers.co/chaingraph/art-129-webbotauth-signature-verifier.html FV-status (published/proven/still-trusted for this spec): /fv-status/8498d0819c941fdb731f9e10f5d93ee929026919cb111a42149821b48b5ac180.json — a snapshot, not a subscription; this receipt verifies offline regardless of whether that file is ever fetched.",
  "inputSchema": {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "properties": {
      "policy_parameters": {
        "description": "Input parameters for this tool's decision function. For gpu:false nodes with a registered kernel, these are computed server-side when compute is \"auto\" or \"server\". See the tool's manifest for field names.",
        "type": "object",
        "propertyNames": {
          "type": "string"
        },
        "additionalProperties": {}
      },
      "compute": {
        "description": "Compute mode (v0.4 Compute Binding). \"auto\" (default) = server for gpu:false nodes with registered kernels; \"server\" = force server-side; \"browser\" = always return browser delegation URL. gpu:true nodes always delegate.",
        "type": "string",
        "enum": [
          "auto",
          "server",
          "browser"
        ]
      },
      "parent_hashes": {
        "description": "execution_hash values from upstream ChainGraph AP2 artifacts to chain from (sets chain.parent_hashes in the export).",
        "type": "array",
        "items": {
          "type": "string"
        }
      },
      "parent_tool_ids": {
        "description": "tool_id values matching parent_hashes, in the same order.",
        "type": "array",
        "items": {
          "type": "string"
        }
      }
    }
  }
}

