{
  "name": "sdjwt_issue",
  "description": "Issues a Selective Disclosure JWT (RFC 9901) from a claims object, marking selected top-level claim keys as selectively disclosable via salted-hash digests in the _sd array. Signed EdDSA over a fresh ephemeral did:key (generated per call, not reused). Pair with sdjwt_present to build a redacted presentation from the returned sd_jwt.",
  "inputSchema": {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "properties": {
      "claims": {
        "type": "object",
        "propertyNames": {
          "type": "string"
        },
        "additionalProperties": {},
        "description": "Claim key-value pairs to issue (required, at least one entry)."
      },
      "selective_keys": {
        "description": "Top-level claim keys marked selectively disclosable. Keys not listed stay always-disclosed cleartext.",
        "type": "array",
        "items": {
          "type": "string"
        }
      },
      "subject": {
        "description": "sub claim. Default: \"subject-001\".",
        "type": "string"
      }
    },
    "required": [
      "claims"
    ]
  }
}

{
  "name": "sdjwt_present",
  "description": "Builds a redacted presentation from an existing SD-JWT (as returned by sdjwt_issue), keeping only the listed disclosures. Pass aud to add a KB-JWT holder-binding (a fresh ephemeral holder key is generated per call). Pass issuer_did (the sd_jwt's \"issuer\" field) to also verify the JWS and return the verifier_view -- exactly the claim set a relying party would resolve -- plus an OCG receipt of the presentation activity.",
  "inputSchema": {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "properties": {
      "sd_jwt": {
        "type": "string",
        "description": "An SD-JWT string with all disclosures attached, as returned by sdjwt_issue."
      },
      "keep_keys": {
        "description": "Disclosure keys to keep in the presentation. Default: none (all disclosures redacted).",
        "type": "array",
        "items": {
          "type": "string"
        }
      },
      "issuer_did": {
        "description": "The sd_jwt's issuer did:key, to verify the JWS and populate verifier_view + receipt.",
        "type": "string"
      },
      "aud": {
        "description": "KB-JWT audience. Supplying this adds a holder-binding KB-JWT to the presentation.",
        "type": "string"
      },
      "nonce": {
        "description": "KB-JWT nonce. Auto-generated if aud is set and this is omitted.",
        "type": "string"
      }
    },
    "required": [
      "sd_jwt"
    ]
  }
}

