{
  "name": "validate_private_inputs",
  "description": "Verify an artifact's private_inputs[] (ChainGraph Standard §25 ocg-private-input@1) WITHOUT ever seeing the plaintext witness: per RFC 6901 pointer, checks the pointed value inside policy_parameters IS the declared sha256-salted@1 commitment (never the plaintext, §25.2), that the commitment scheme is known, and -- when a §18 compute_proof is present -- that its journal commits the same commitment and binds output_payload. Optionally accepts an out-of-band {pointer, salt, input_value} disclosure package (authorized-verifier path) and recomputes sha256(salt || cgCanon(input_value)) to confirm it equals the commitment. Returns one {pointer, verifiable} record per entry: \"proof-only\" | \"disclosed-verified\" | \"commitment-only\" (no proof yet -- structural + plaintext-exclusion only) | \"failed\". Pure client-safe compute, zero network, never requires the plaintext.",
  "inputSchema": {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "properties": {
      "artifact": {
        "description": "A full ChainGraph artifact envelope carrying private_inputs[], policy_parameters, and optionally output_payload + audit_signature.compute_proof.",
        "type": "object",
        "propertyNames": {
          "type": "string"
        },
        "additionalProperties": {}
      },
      "policy_parameters": {
        "description": "Artifact policy_parameters (if not passing a full artifact).",
        "type": "object",
        "propertyNames": {
          "type": "string"
        },
        "additionalProperties": {}
      },
      "output_payload": {
        "description": "Artifact output_payload (if not passing a full artifact).",
        "type": "object",
        "propertyNames": {
          "type": "string"
        },
        "additionalProperties": {}
      },
      "private_inputs": {
        "description": "The private_inputs[] array (if not passing a full artifact).",
        "type": "array",
        "items": {
          "type": "object",
          "propertyNames": {
            "type": "string"
          },
          "additionalProperties": {}
        }
      },
      "compute_proof": {
        "description": "audit_signature.compute_proof (if not passing a full artifact).",
        "type": "object",
        "propertyNames": {
          "type": "string"
        },
        "additionalProperties": {}
      },
      "disclosures": {
        "description": "OPTIONAL authorized-verifier disclosure packages, keyed by pointer, for the disclosed-verified path.",
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "pointer": {
              "type": "string"
            },
            "salt": {
              "type": "string",
              "description": ">=256-bit hex CSPRNG salt, out-of-band disclosure material."
            },
            "input_value": {
              "description": "The plaintext private input value, out-of-band."
            }
          },
          "required": [
            "pointer",
            "salt",
            "input_value"
          ]
        }
      }
    }
  }
}

