{
  "name": "build_evidence_pack",
  "description": "Composes a session receipt (build_session_receipt logic), an optional §27.6 HA evidence bundle (ha_bundle_export logic, included only when ha_records is supplied and non-empty), and a disclosure manifest (build_disclosure_manifest logic) from one array of already-produced artifacts, all keyed to the same input hashes -- replacing what today takes 4-6 separate tool calls with hand-carried hashes. Calls the same in-process functions those standalone tools use; if any one section fails to build, the whole call fails isError:true with that section's own message -- no partial pack. Optionally carries a run_chain decision_trail (per-step reason codes: gate rule id, escalation rule id, input_required cause) as pack-level metadata so an auditor-facing pack answers \"why did each step happen\" without a second round-trip.",
  "inputSchema": {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "properties": {
      "artifacts": {
        "minItems": 1,
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "execution_hash": {
              "type": "string",
              "description": "sha256:... -- the OCG artifact hash this entry documents."
            },
            "tool_id": {
              "description": "The tool_id that produced this artifact, if known.",
              "type": "string"
            },
            "output_payload": {
              "description": "Present when caller has the full artifact, not just its hash.",
              "type": "object",
              "propertyNames": {
                "type": "string"
              },
              "additionalProperties": {}
            }
          },
          "required": [
            "execution_hash"
          ]
        },
        "description": "Already-produced artifacts this pack documents, in call order."
      },
      "subject_hash": {
        "description": "The sha256: subject hash the pack documents (defaults to artifacts[0].execution_hash if omitted).",
        "type": "string"
      },
      "ha_records": {
        "description": "§27 human_accountability_records -- omit entirely for no HA section.",
        "type": "array",
        "items": {
          "type": "object",
          "propertyNames": {
            "type": "string"
          },
          "additionalProperties": {}
        }
      },
      "kernel_version": {
        "description": "Version tag of the kernel that produced verification_result.",
        "type": "string"
      },
      "policy_version": {
        "description": "Version tag of the policy the kernel was evaluated against.",
        "type": "string"
      },
      "verification_result": {
        "description": "The §16/§18/§20 verdict.",
        "type": "string"
      },
      "submission_receipt": {
        "description": "Populate ONLY after a real transmission -- never fabricate (same rule as ha_bundle_export).",
        "type": "string"
      },
      "session_id": {
        "description": "Session identifier to embed in the receipt, if the caller tracks one.",
        "type": "string"
      },
      "framing": {
        "description": "Optional framing context for the session receipt's PTG-01 regulator prompt.",
        "type": "string"
      },
      "room_label": {
        "description": "Label for the disclosure-manifest room.",
        "type": "string"
      },
      "decision_trail": {
        "description": "Per-step decision reason trail from the run_chain result (pass its decision_trail — response field or composite_output.decision_trail). Carried verbatim into the pack as pack-level metadata, outside every section hash; omitted entirely when not supplied. See DECISIONTRAIL-1.",
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "order": {
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991,
              "description": "1-based step order, mirroring the producing run_chain result."
            },
            "tool_id": {
              "type": "string",
              "description": "The step's tool_id."
            },
            "status": {
              "type": "string",
              "description": "Per-step status from the run_chain result."
            },
            "reason_code": {
              "type": "string",
              "description": "Closed enum: ran | gate_routed | skipped_by_gate | skipped_by_escalation | input_required | unknown_node | gpu_browser_only | no_kernel_browser_only."
            },
            "gate_rule_id": {
              "description": "<step_id>#r<index> or <step_id>#default — the gate rule that fired or bypassed this step. Recomputable from the hash-bound decisions[].",
              "type": "string"
            },
            "decided_by": {
              "description": "step_id of the decision that routed control past this step.",
              "type": "string"
            },
            "next": {
              "description": "Routing target of the gate decision (a step id, or the terminal \"end\"/\"escalate\").",
              "type": "string"
            },
            "input_required_cause": {
              "description": "The kernel error that made this step input_required.",
              "type": "string"
            }
          },
          "required": [
            "order",
            "tool_id",
            "status",
            "reason_code"
          ]
        }
      },
      "sd_jwt": {
        "description": "When true, also return an SD-JWT export of the HA bundle (mirrors ha_bundle_export, default false; no-op when ha_records is absent).",
        "type": "boolean"
      }
    },
    "required": [
      "artifacts"
    ]
  }
}

{
  "name": "workbook_csv_parse",
  "description": "Parses CSV text with the SAME strict RFC 4180 parser as the tools/554 browser workbook -- quoted fields, embedded quotes/commas/newlines, CRLF -- and REJECTS malformed input rather than repairing it (deterministic beats forgiving for hash-stable digests). Numeric-looking and TRUE/FALSE cells are type-coerced; everything else stays a string. Returns the resulting A1-style cells (raw + evaluated value) plus the sheet's row/column extent, ready for workbook_evaluate or workbook_range_digest -- unless as_artifact is true, in which case it returns a full OCG v0.4 artifact instead (see as_artifact).",
  "inputSchema": {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "properties": {
      "csv": {
        "type": "string",
        "description": "CSV text to parse."
      },
      "as_artifact": {
        "description": "When true, returns a full OpenChainGraph v0.4 artifact (policy_parameters/output_payload/execution_hash/provenance) via the same exportArtifact() path as the tools/554 browser workbook's \"Export as OCG Artifact\" button, instead of this tool's normal bare payload. Default false.",
        "type": "boolean"
      },
      "provenance": {
        "description": "Optional provenance metadata, only used when as_artifact is true. Never affects execution_hash.",
        "type": "object",
        "properties": {
          "source_description": {
            "description": "Free-text description of what this sheet is (provenance, not hashed).",
            "type": "string"
          },
          "created_by": {
            "description": "Identity slot for who/what produced this sheet -- free text or did:key (provenance, not hashed).",
            "type": "string"
          }
        }
      }
    },
    "required": [
      "csv"
    ]
  }
}

{
  "name": "workbook_evaluate",
  "description": "Feeds a set of A1-style cells (formulas and/or literals) through the SAME headless evaluator the tools/554 browser workbook uses -- topo-sorted dependency graph, ~20 functions (SUM AVG MIN MAX COUNT COUNTIF IF AND OR NOT ROUND ABS CONCAT LEN LEFT RIGHT TRIM UPPER LOWER SUMIF), cycles resolve to \"#CYCLE!\" and any non-finite result to \"#NUM!\" rather than propagating. Returns the computed value of every supplied cell -- pure, no digest, no receipt -- unless as_artifact is true, in which case it returns a full OCG v0.4 artifact instead (see as_artifact).",
  "inputSchema": {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "properties": {
      "cells": {
        "type": "object",
        "propertyNames": {
          "type": "string"
        },
        "additionalProperties": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "number"
            },
            {
              "type": "boolean"
            }
          ]
        },
        "description": "Map of A1-style cell ref (e.g. \"B2\") to raw value -- a formula string starts with \"=\" (e.g. \"=SUM(A1:A3)\"), anything else is a literal."
      },
      "as_artifact": {
        "description": "When true, returns a full OpenChainGraph v0.4 artifact (policy_parameters/output_payload/execution_hash/provenance) via the same exportArtifact() path as the tools/554 browser workbook's \"Export as OCG Artifact\" button, instead of this tool's normal bare payload. Default false.",
        "type": "boolean"
      },
      "provenance": {
        "description": "Optional provenance metadata, only used when as_artifact is true. Never affects execution_hash.",
        "type": "object",
        "properties": {
          "source_description": {
            "description": "Free-text description of what this sheet is (provenance, not hashed).",
            "type": "string"
          },
          "created_by": {
            "description": "Identity slot for who/what produced this sheet -- free text or did:key (provenance, not hashed).",
            "type": "string"
          }
        }
      }
    },
