          "mmr_size"
        ]
      }
    },
    "required": [
      "execution_hashes"
    ]
  }
}

{
  "name": "redline_diff",
  "description": "An agent proposes an edit: diffs original text/markdown against its own revised version and returns the line-level hunks plus a diff receipt (original/revised digests, diff-algorithm declaration, per-hunk digests). Byte-identical to what the tools/552 browser workbench computes for the same inputs -- a human can paste the SAME original/revised text into that workbench, disposition each hunk (accept/reject/comment), and their resulting hunk/disposition receipts will reference this diff_receipt's execution_hash. Pass the whole bundle (this diff_receipt + the human's hunk_receipts + disposition_receipt) to redline_verify to check the interleaved chain end-to-end.",
  "inputSchema": {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "properties": {
      "original": {
        "type": "string",
        "description": "Original text or markdown document."
      },
      "revised": {
        "type": "string",
        "description": "Proposed revised text or markdown document."
      },
      "generated_at": {
        "description": "ISO 8601 timestamp (caller-supplied for determinism). Defaults to the call time.",
        "type": "string"
      }
    },
    "required": [
      "original",
      "revised"
    ]
  }
}

{
  "name": "redline_verify",
  "description": "Recomputes a redline review from scratch: the diff (from the pasted original+revised text), the diff_receipt's execution_hash, every hunk_receipt's digest/execution_hash/chain-link (in the order supplied -- entries may be minted by an agent, a human, or both interleaved), the disposition_receipt's execution_hash, and the accepted-text digest. Returns valid:true/false, a per-check breakdown, and broken_hunk (the zero-based index of the first divergence, or null) -- never trusts a bundle claim without checking it against a fresh recomputation.",
  "inputSchema": {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "properties": {
      "original": {
        "type": "string",
        "description": "Original text or markdown document."
      },
      "revised": {
        "type": "string",
        "description": "Revised text or markdown document."
      },
      "bundle": {
        "type": "object",
        "properties": {
          "diff_receipt": {
            "type": "object",
            "propertyNames": {
              "type": "string"
            },
            "additionalProperties": {},
            "description": "The diff receipt (from redline_diff or the browser workbench)."
          },
          "hunk_receipts": {
            "type": "array",
            "items": {
              "type": "object",
              "propertyNames": {
                "type": "string"
              },
              "additionalProperties": {}
            },
            "description": "Ordered hunk disposition receipts, one per hunk index."
          },
          "disposition_receipt": {
            "type": "object",
            "propertyNames": {
              "type": "string"
            },
            "additionalProperties": {},
            "description": "The closing disposition receipt binding the accepted-text digest."
          }
        },
        "required": [
          "diff_receipt",
          "hunk_receipts",
          "disposition_receipt"
        ],
        "description": "The redline receipt bundle to verify."
      }
    },
    "required": [
      "original",
      "revised",
      "bundle"
    ]
  }
}

