{
  "name": "build_session_receipt",
  "description": "Aggregates execution_hashes from N ChainGraph tool calls in one agent session into a single SHA-256 Merkle root (session_receipt_root). Returns a tamper-evident session receipt and a regulator-framed PTG-01 audit prompt. One receipt covers an entire agent session: supply all execution_hashes in call order. The Merkle root is deterministic — the same hashes in the same order always produce the same root. Compliant with EU AI Act Art. 12 (transparency) and DORA ICT audit-trail requirements.",
  "inputSchema": {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "properties": {
      "execution_hashes": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Ordered list of execution_hash values from ChainGraph tool calls in this session (each produced by emit_chaingraph_artifact or a kernel tool). Minimum 1."
      },
      "tool_ids": {
        "description": "tool_id values corresponding to execution_hashes, in the same order. Used for the audit narrative.",
        "type": "array",
        "items": {
          "type": "string"
        }
      },
      "session_id": {
        "description": "Optional agent session identifier for the audit narrative (e.g. a UUID or timestamp).",
        "type": "string"
      },
      "framing": {
        "description": "Optional framing context for the PTG-01 regulator prompt (e.g. \"DORA incident review\" or \"EU AI Act Art.12 transparency log\").",
        "type": "string"
      },
      "prior_receipt": {
        "description": "An earlier receipt from this SAME session (its mmr_peaks/mmr_size/mmr_bagged_root). When supplied, execution_hashes MUST start with that earlier receipt's full leaf set — the response's consistency_proof then proves this receipt provably APPENDS to the prior one (CT-style append-only guarantee) without operating a log.",
        "type": "object",
        "properties": {
          "mmr_peaks": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "mmr_size": {
            "type": "number"
          },
          "mmr_bagged_root": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ]
          }
        },
        "required": [
          "mmr_peaks",
          "mmr_size"
        ]
      }
    },
    "required": [
      "execution_hashes"
    ]
  }
}

